import{_ as e,o as a,c as i,a5 as s}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"コードへの貢献","description":"","frontmatter":{"title":"コードへの貢献","order":3},"headers":[],"relativePath":"ja/latest/community/code-contribute.md","filePath":"ja/latest/community/code-contribute.md","lastUpdated":1788455378000}'),l={name:"ja/latest/community/code-contribute.md"};function o(n,t,r,d,p,c){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="コード貢献ガイド" tabindex="-1">コード貢献ガイド <a class="header-anchor" href="#コード貢献ガイド" aria-label="Permalink to &quot;コード貢献ガイド&quot;">​</a></h1><h2 id="貢献方法" tabindex="-1">貢献方法 <a class="header-anchor" href="#貢献方法" aria-label="Permalink to &quot;貢献方法&quot;">​</a></h2><p>ドキュメント、コード、その他の内容は、以下の方法で貢献できます。</p><ul><li><strong>Pull Request</strong>：コードをリポジトリへ提出し、コードレビュー後にメインブランチへマージします</li><li><strong>Issue</strong>：問題や提案を提出し、議論のうえで実装するかどうかを決め、開発者へ割り当てます</li></ul><h2 id="コード貢献の流れ" tabindex="-1">コード貢献の流れ <a class="header-anchor" href="#コード貢献の流れ" aria-label="Permalink to &quot;コード貢献の流れ&quot;">​</a></h2><p>コードを提出する前に、ローカルで Git のグローバル設定が完了していることを確認してください。ローカル Git のコミットメールアドレスとユーザー名は、<strong>プラットフォームに登録されているメールアドレスとユーザー名に一致している必要があります</strong>。一致していない場合、誤ったコミット記録が作成され、貢献者一覧に反映されません。</p><p>メールアドレスとユーザー名が正しいか不明な場合は、ターミナルで Git 設定を確認してください。</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span></span></code></pre></div><p>変更が必要な場合は、以下のコマンドを使用します。&quot;Your Name&quot; と &quot;<a href="mailto:your.email@example.com" target="_blank" rel="noreferrer">your.email@example.com</a>&quot; をそれぞれ自分のユーザー名とメールアドレスに置き換えてください。</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Your Name&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your.email@example.com&quot;</span></span></code></pre></div><p>設定完了後は、設定を確実に反映するためにターミナルを再起動することを推奨します。</p><ol><li><strong>プロジェクトを Fork</strong>：右上の Fork をクリックして自分のリポジトリにコピーします</li><li><strong>ブランチを作成</strong>：<code>git checkout -b feature/your-feature</code></li><li><strong>変更をコミット</strong>：<code>git commit -m &quot;feat: 変更内容を説明&quot;</code></li><li><strong>ブランチをプッシュ</strong>：<code>git push origin feature/your-feature</code></li><li><strong>PR を提出</strong>：Pull Request を作成します</li></ol><p>貢献されたコードはコードレビューを経て、承認後にメインブランチへマージされます。</p><h2 id="gdscript-コーディング規約の参考" tabindex="-1">GDScript コーディング規約の参考 <a class="header-anchor" href="#gdscript-コーディング規約の参考" aria-label="Permalink to &quot;GDScript コーディング規約の参考&quot;">​</a></h2><p>本プロジェクトは Godot 公式ドキュメントの <a href="https://docs.godotengine.org/ja/4.x/tutorials/scripting/gdscript/gdscript_styleguide.html" target="_blank" rel="noreferrer">GDScript スタイルガイド</a> に従います。以下は参考規約です。</p><h3 id="フォーマット規約" tabindex="-1">フォーマット規約 <a class="header-anchor" href="#フォーマット規約" aria-label="Permalink to &quot;フォーマット規約&quot;">​</a></h3><ul><li><strong>インデント</strong>：スペースではなくタブを使用し、インデント 1 段階につきタブ 1 つを使います</li><li><strong>行の長さ</strong>：100 文字以内に抑え、できれば 80 文字以下にします。長すぎると読みづらくなります</li><li><strong>改行</strong>：LF 改行を使用し、ファイル末尾には改行を残して Git の競合を避けます</li><li><strong>エンコーディング</strong>：文字化けを避けるため UTF-8 without BOM を使用します</li></ul><p>通常、Godot 標準のスクリプトエディターや VSCode を使えば、これらのフォーマット規約を自動的に満たせます。他のエディターを使う場合は、これらの規約に注意してください。</p><h3 id="命名規約" tabindex="-1">命名規約 <a class="header-anchor" href="#命名規約" aria-label="Permalink to &quot;命名規約&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要素の種類</th><th>命名スタイル</th><th>例</th></tr></thead><tbody><tr><td>ファイル名</td><td>snake_case</td><td><code>player_controller.gd</code></td></tr><tr><td>クラス名</td><td>PascalCase</td><td><code>class_name PlayerController</code></td></tr><tr><td>関数/変数</td><td>snake_case</td><td><code>func move_player()</code></td></tr><tr><td>シグナル</td><td>snake_case（過去形）</td><td><code>signal door_opened</code></td></tr><tr><td>定数</td><td>CONSTANT_CASE</td><td><code>const MAX_HEALTH = 100</code></td></tr><tr><td>enum 名</td><td>PascalCase</td><td><code>enum GameState</code></td></tr><tr><td>enum 値</td><td>CONSTANT_CASE</td><td><code>IDLE, RUNNING, JUMPING</code></td></tr></tbody></table><p>スクリプト内の命名には英語のみを使用してください。他の言語は問題の原因になる可能性があるため使用しないでください。</p><h3 id="コメント規約" tabindex="-1">コメント規約 <a class="header-anchor" href="#コメント規約" aria-label="Permalink to &quot;コメント規約&quot;">​</a></h3><ul><li><strong>クラスコメント</strong>：各クラスの先頭には、その機能と使い方を説明するコメントが必要です。このコメントは自動的にドキュメントへ生成されるため、できるだけ詳しく書いてください</li><li><strong>関数コメント</strong>：各 public 関数の先頭には、関数の機能、引数、戻り値を説明するコメントが必要です。private 関数や内部ユーティリティ関数では省略できます</li><li><strong>変数コメント</strong>：必要な変数、特に特定の意味や用途を持つ変数にはコメントを付けることを推奨します</li><li><strong>シグナルコメント</strong>：各シグナルの先頭には、用途と引数を説明するコメントが必要です</li><li><strong>TODO コメント</strong>：TODO を追加する場合は <code>TODO</code> コメントを使用し、内容と優先度を説明してください</li></ul><h2 id="コミット規約" tabindex="-1">コミット規約 <a class="header-anchor" href="#コミット規約" aria-label="Permalink to &quot;コミット規約&quot;">​</a></h2><p>オープンソースプロジェクトでは、コミットメッセージの規約を学び適応するために初期コストがかかりますが、長期的な効果は非常に大きいです。「厳格な」メッセージ規約は、開発者間の理解とコミュニケーションの時間を節約し、CHANGELOG の生成もより簡単で標準化されたものにします。</p><h3 id="commit-メッセージ" tabindex="-1">Commit メッセージ <a class="header-anchor" href="#commit-メッセージ" aria-label="Permalink to &quot;Commit メッセージ&quot;">​</a></h3><p>本プロジェクトは Conventional Commits 1.0.0 を参考にしています。形式は以下のとおりです。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;(&lt;scope)&gt;: &lt;subject&gt;</span></span></code></pre></div><p>3 つのフィールドで構成されます：<code>type</code>（必須）、<code>scope</code>（任意）、<code>subject</code>（必須）。</p><p><strong><code>type</code>（種類）</strong> は commit の分類を示します。以下のいずれかを使用してください。</p><table tabindex="0"><thead><tr><th style="text-align:left;">種類</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>feat</strong></td><td style="text-align:left;">新機能（feature）</td></tr><tr><td style="text-align:left;"><strong>fix</strong></td><td style="text-align:left;">bug 修正</td></tr><tr><td style="text-align:left;"><strong>docs</strong></td><td style="text-align:left;">ドキュメント変更（documentation）</td></tr><tr><td style="text-align:left;"><strong>test</strong></td><td style="text-align:left;">テストの追加または既存テストの変更</td></tr><tr><td style="text-align:left;"><strong>ci</strong></td><td style="text-align:left;">CI 設定ファイルやスクリプトの変更</td></tr></tbody></table><p><strong><code>scope</code>（範囲）</strong> は commit が影響する範囲を示し、プロジェクトに応じてモジュール、コンポーネント、ファイルなどを指定できます。</p><ul><li><code>feat(something): ...</code></li><li><code>fix(ui): ...</code></li><li><code>docs(readme): ...</code></li><li>影響範囲が広い場合は省略するか <code>(*)</code> を使用できます。</li></ul><p><strong><code>subject</code>（件名）</strong> は今回の commit の目的を短く説明します。</p><p>例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feat(xxx): リプレイ機能を追加</span></span>
<span class="line"><span>fix: リプレイ機能で再生速度が速すぎるとクラッシュする問題を修正</span></span>
<span class="line"><span>docs(readme): readme を更新</span></span></code></pre></div><h3 id="pull-request" tabindex="-1">Pull Request <a class="header-anchor" href="#pull-request" aria-label="Permalink to &quot;Pull Request&quot;">​</a></h3><p>PR（Pull Request）は、あなたのコードをメインリポジトリのメインブランチへ提出するために使います。PR を提出する前に、コードが以下の規約を満たしていることを確認してください。</p><ol><li>コードのフォーマットがプロジェクトのコードスタイルに合っている。</li><li>コミットメッセージが Git Commit メッセージ規約に合っている。</li><li>提出するコードがテスト済みで、既知の問題がない。</li></ol><p>これらの条件をおおむね満たしていれば、PR を提出できます。</p><h3 id="pr-提出規約" tabindex="-1">PR 提出規約 <a class="header-anchor" href="#pr-提出規約" aria-label="Permalink to &quot;PR 提出規約&quot;">​</a></h3><p>PR 情報には以下を含めてください。</p><ol><li><strong>タイトル</strong>：PR の内容を簡潔かつ明確に説明します。Git Commit メッセージを使っても構いません。</li><li><strong>説明</strong>：PR の内容を詳しく説明します。機能説明、実装方法、影響範囲などを含めてください。</li><li><strong>issue 関連付け</strong>：PR がいくつかの issue を修正する場合は、PR 情報に issue のリンクを追加してください。</li></ol><div class="tip custom-block"><p class="custom-block-title">その他の提案</p><ol><li>メンテナーの時間と労力を節約するため、PR の説明はできるだけ詳しくしてください。</li><li>単純な bug 修正や文章修正以外では、変更内容を細かく説明する PR 本文を書くことを推奨します。</li><li>PR 内の commit 内容を修正する必要がある場合があります。PR コメント欄の議論を随時確認してください。</li><li>すべての PR がマージされるわけではありません。あらかじめご了承ください。</li></ol></div><h2 id="コードレビュー" tabindex="-1">コードレビュー <a class="header-anchor" href="#コードレビュー" aria-label="Permalink to &quot;コードレビュー&quot;">​</a></h2><h3 id="レビューの流れ" tabindex="-1">レビューの流れ <a class="header-anchor" href="#レビューの流れ" aria-label="Permalink to &quot;レビューの流れ&quot;">​</a></h3><p>PR 提出後、プロジェクトメンテナーがコードをレビューします。レビュー中、メンテナーはコードスタイル、パフォーマンス最適化、セキュリティ改善など、さまざまな改善提案を行う場合があります。メンテナーの提案をよく読み、提案に従って修正してください。</p><h3 id="レビュー基準" tabindex="-1">レビュー基準 <a class="header-anchor" href="#レビュー基準" aria-label="Permalink to &quot;レビュー基準&quot;">​</a></h3><p>コードレビューでは、プロジェクトメンテナーは以下の基準に従います。</p><ol><li><strong>コードスタイル</strong>：コードスタイルがプロジェクトのスタイルガイドに合っていることを確認します。</li><li><strong>パフォーマンス最適化</strong>：コードに重大なパフォーマンス問題がある場合は、最適化案を提示してください。</li><li><strong>ドキュメント更新</strong>：コード変更がドキュメントに影響する場合は、対応するドキュメントを更新してください。</li></ol><div class="tip custom-block"><p class="custom-block-title">ヘルプを求める</p><p>多くの場合、プロジェクトメンテナーはコードレビュー中に発生した問題の解決を支援し、コードがメインブランチへスムーズにマージされるようサポートします。助けが必要な場合は、PR コメント欄の議論を確認してください。</p></div><h2 id="メンテナーへの応募" tabindex="-1">メンテナーへの応募 <a class="header-anchor" href="#メンテナーへの応募" aria-label="Permalink to &quot;メンテナーへの応募&quot;">​</a></h2><p>プロジェクトに一定数の PR 貢献を行うと、メンテナーに応募する資格が得られます。メンテナーになりたい場合は、以下の手順でメールを送って申請してください。</p><ol><li><p>個人の Git アカウント情報（ユーザー名、メールアドレス）を準備してください。これは貢献記録の確認と、後日の招待メール送信に使用します。</p></li><li><p>プロジェクトへの貢献情報を準備してください。これには、これまで提出・マージされた PR リンク、議論への参加回数、報告した Issue 数などが含まれます。</p></li><li><p><code>konado@godothub.com</code> へメールを送信してください。件名は「Konado メンテナー応募」とし、本文に上記情報を含めてください。</p></li><li><p>希望する場合は、興味、スキル、オープンソースプロジェクトへの参加経験などを含む自己紹介を添えてください。私たちがあなたをよりよく理解する助けになります。</p></li></ol><p>プロジェクトメンテナーチームは、できるだけ早く申請へ返信します。貢献記録を確認した後、あなたのメールアドレスへ招待メールを送信します。メール内の指示に従って、メンテナー身份の確認とリポジトリ権限の設定を完了してください。</p><p>Konado プロジェクトの一員となり、私たちと一緒にオープンソースコミュニティへ貢献していただけることを期待しています！</p>`,56)])])}const u=e(l,[["render",o]]);export{g as __pageData,u as default};
